/* Begleiter (Vertraute, Reittiere): eigene Bilder; Imp, Mastiff, Wolf und Bär nehmen das Bild aus dem Bestiarium */
const COMP_PIC = {
 'custom':'data:image/webp;base64,',
 'f-bat':'data:image/webp;base64,',
 'f-cat':'data:image/webp;base64,',
 'f-frog':'data:image/webp;base64,',
 'f-hawk':'data:image/webp;base64,',
 'f-owl':'data:image/webp;base64,',
 'f-rat':'data:image/webp;base64,',
 'f-raven':'data:image/webp;base64,',
 'f-spider':'data:image/webp;base64,',
 'm-horse':'data:image/webp;base64,',
 'm-mule':'data:image/webp;base64,',
 'm-pony':'data:image/webp;base64,',
 'm-warhorse':'data:image/webp;base64,',
 'steed':'data:image/webp;base64,',
};
const COMP_PIC_MOB = { 'f-imp': 'imp', 'm-mastiff': 'mastiff', 'w-wolf': 'wolf', 'w-bear': 'brown-bear', 'w-hawk': '' };
const compPicSrc = (t) => COMP_PIC[t] || (t === 'w-hawk' ? COMP_PIC['f-hawk'] : MOB_PIC[COMP_PIC_MOB[t]]) || '';
const compPic = (t, cls) => { const u = compPicSrc(t); return u ? '<img class="' + (cls || 'cmpic') + '" src="' + imgUrl(u) + '" alt="" loading="lazy" decoding="async">' : ''; };
/* Eigene Monster ohne eigenes Bild: Platzhalter (Silhouette im Nebel) */
const MOB_PH = 'data:image/webp;base64,';
const mobPicSrc = (mid) => (mid ? MOB_PIC[mid] || (/^u-/.test(mid) ? MOB_PH : '') : '');
const mobPic = (mid, cls) => (mobPicSrc(mid) ? '<img class="' + (cls || 'mpic') + '" src="' + imgUrl(mobPicSrc(mid)) + '" alt=""" loading="lazy" decoding="async">' : '');
